// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./verifiers/IGroth16Verifier.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title CardDrawGame
 * @dev F9: Multiplayer Card Draw Game (Commit-Reveal scheme).
 *
 *      SECURITY: Two-phase design prevents seed cherry-picking.
 *
 *      Phase 1 – COMMIT (Open):
 *        joinGame(deckCommitment, playerCommitment) — pay entry fee + commit to deck.
 *        No ZK proof required. drawIndex is NOT yet determined.
 *        Player doesn't know their card result at this point.
 *
 *      Phase 1.5 – PENDING REVEAL (PendingReveal):
 *        startReveal() — anyone calls after commit phase ends.
 *          Records revealBlock = block.number + 2. Status → PendingReveal.
 *          The seed block does not exist yet, so nobody can predict the seed.
 *
 *      Phase 2 – REVEAL (Revealing):
 *        finalizeReveal() — anyone calls once block.number > revealBlock.
 *          revealSeed = blockhash(revealBlock)  ← block that didn't exist at startReveal time
 *          Each player's drawIndex = keccak256(revealSeed, playerAddr, gameId) % 52
 *        revealCard(ZK proof) — player proves deckCards[drawIndex] = drawnCard.
 *          Only now is the card deterministic; seed can't be pre-simulated.
 *
 *      CLOSE: Winner = highest card among revealed players.
 *             Unrevealed players forfeit their entry fee.
 *
 *      Circuit public inputs (unchanged): [deckCommitment, drawCommitment, drawIndex, gameId, playerCommitment]
 */
contract CardDrawGame {
    ICardDrawVerifier public drawVerifier;
    IERC20 public paymentToken;
    address public admin;

    uint256 public constant MAX_PLAYERS = 5;
    uint256 public constant MIN_PLAYERS = 2;
    uint256 public constant FEE_PERCENT = 10;
    uint256 public constant REVEAL_TIMEOUT = 120; // 2 minutes to reveal after startReveal

    uint256 public entryFee;
    uint256 public defaultCommitTimeout; // seconds after last join before startReveal is allowed
    uint256 public nextGameId = 1;

    enum GameStatus { Open, PendingReveal, Revealing, Finished, Cancelled }

    struct Game {
        address creator;
        GameStatus status;
        uint256 commitTimeout;     // seconds after last join before startReveal is allowed
        uint256 lastJoinTime;      // updated on every join
        uint256 playerCount;
        uint256 revealedCount;
        uint256 prizePool;
        uint256 revealBlock;           // target block for seed (set by startReveal, doesn't exist yet)
        uint256 prevRandaoSnapshot;    // block.prevrandao captured at startReveal time
        uint256 revealSeed;            // set by finalizeReveal(): keccak256(blockhash(revealBlock), prevRandaoSnapshot)
        uint256 revealDeadline;        // set by finalizeReveal(): finalizeTime + REVEAL_TIMEOUT
        address winner;
        uint256 highestCardValue;
        uint256 createdAt;
    }

    struct Player {
        address addr;
        bytes32 deckCommitment;
        bytes32 playerCommitment;
        uint256 drawnCard;         // 0-51, only valid after reveal
        bool hasCommitted;
        bool hasRevealed;
    }

    mapping(uint256 => Game) public games;
    mapping(uint256 => Player[]) internal _players;
    mapping(uint256 => mapping(address => bool)) public hasJoined;
    mapping(uint256 => mapping(address => uint256)) internal _playerIndex;
    uint256 public accumulatedFees;

    event GameCreated(uint256 indexed gameId, address indexed creator, uint256 commitTimeout);
    event PlayerCommitted(uint256 indexed gameId, address indexed player, uint256 playerCount);
    event RevealPending(uint256 indexed gameId, uint256 revealBlock);
    event RevealStarted(uint256 indexed gameId, uint256 revealSeed, uint256 revealDeadline);
    event PlayerRevealed(uint256 indexed gameId, address indexed player, uint256 drawnCard, uint256 drawIndex);
    event GameFinished(uint256 indexed gameId, address indexed winner, uint256 prize, uint256 highestCard);
    event GameCancelled(uint256 indexed gameId);

    constructor(
        address _drawVerifier,
        address _paymentToken,
        uint256 _entryFee,
        uint256 _defaultCommitTimeout
    ) {
        drawVerifier = ICardDrawVerifier(_drawVerifier);
        paymentToken = IERC20(_paymentToken);
        admin = msg.sender;
        entryFee = _entryFee;
        defaultCommitTimeout = _defaultCommitTimeout;
    }

    // ─── Phase 0: Create ───────────────────────────────────────────────────────

    /**
     * @dev Create a new game room.
     * @param commitTimeout Seconds after the last player joins before startReveal is callable.
     */
    function createGame(uint256 commitTimeout) external returns (uint256 gameId) {
        require(commitTimeout >= 30, "Commit timeout must be >= 30 seconds");

        gameId = nextGameId++;
        games[gameId] = Game({
            creator: msg.sender,
            status: GameStatus.Open,
            commitTimeout: commitTimeout,
            lastJoinTime: 0,
            playerCount: 0,
            revealedCount: 0,
            prizePool: 0,
            revealBlock: 0,
            prevRandaoSnapshot: 0,
            revealSeed: 0,
            revealDeadline: 0,
            winner: address(0),
            highestCardValue: 0,
            createdAt: block.timestamp
        });

        emit GameCreated(gameId, msg.sender, commitTimeout);
    }

    // ─── Phase 1: Commit ───────────────────────────────────────────────────────

    /**
     * @dev Commit phase: pay entry fee + commit to deck. NO ZK proof required.
     *      Player does not know their final card at this point
     *      (drawIndex is determined only after startReveal, from on-chain randomness).
     *
     * @param deckCommitment  Poseidon commitment to the player's shuffled deck
     * @param playerCommitment Poseidon(playerPkX, playerPkY, gameId)
     */
    function joinGame(
        uint256 gameId,
        bytes32 deckCommitment,
        bytes32 playerCommitment
    ) external {
        Game storage game = games[gameId];
        require(game.creator != address(0), "Game does not exist");
        require(game.status == GameStatus.Open, "Game is not in commit phase");
        require(!hasJoined[gameId][msg.sender], "Already joined");
        require(game.playerCount < MAX_PLAYERS, "Game is full");

        // Once MIN_PLAYERS joined, check the commit window
        if (game.playerCount >= MIN_PLAYERS && game.lastJoinTime > 0) {
            require(
                block.timestamp <= game.lastJoinTime + game.commitTimeout,
                "Commit phase has ended"
            );
        }

        // Transfer entry fee
        require(
            paymentToken.transferFrom(msg.sender, address(this), entryFee),
            "Entry fee transfer failed"
        );

        // Record commitment (no ZK proof, drawnCard unknown)
        uint256 playerIdx = _players[gameId].length;
        _players[gameId].push(Player({
            addr: msg.sender,
            deckCommitment: deckCommitment,
            playerCommitment: playerCommitment,
            drawnCard: 0,
            hasCommitted: true,
            hasRevealed: false
        }));
        _playerIndex[gameId][msg.sender] = playerIdx;
        hasJoined[gameId][msg.sender] = true;
        game.playerCount++;
        game.prizePool += entryFee;
        game.lastJoinTime = block.timestamp;

        emit PlayerCommitted(gameId, msg.sender, game.playerCount);
    }

    // ─── Phase 1 → 2: Transition ───────────────────────────────────────────────

    /**
     * @dev Phase 1 → 1.5: Record the target block for seed derivation.
     *      Anyone can call once the commit phase has ended.
     *
     *      Sets revealBlock = block.number + 2.
     *      That block does not exist yet, so no one can know blockhash(revealBlock)
     *      at call time — preventing validator seed cherry-picking.
     *
     *      Also snapshots block.prevrandao at this moment.
     *      Final seed = keccak256(blockhash(revealBlock), prevRandaoSnapshot).
     *      Manipulating the seed requires colluding BOTH:
     *        - the startReveal caller (controls prevRandaoSnapshot timing), AND
     *        - the revealBlock producer (controls blockhash).
     */
    function startReveal(uint256 gameId) external {
        Game storage game = games[gameId];
        require(game.status == GameStatus.Open, "Game is not in commit phase");
        require(game.playerCount >= MIN_PLAYERS, "Not enough players");
        require(
            game.playerCount >= MAX_PLAYERS ||
            block.timestamp > game.lastJoinTime + game.commitTimeout,
            "Commit phase has not ended yet"
        );

        game.revealBlock = block.number + 2;
        game.prevRandaoSnapshot = block.prevrandao;
        game.status = GameStatus.PendingReveal;

        emit RevealPending(gameId, game.revealBlock);
    }

    /**
     * @dev Phase 1.5 → 2: Derive revealSeed from the now-known target block hash
     *      combined with the prevrandao snapshot captured at startReveal.
     *      Anyone can call once block.number > revealBlock.
     *
     *      revealSeed = keccak256(blockhash(revealBlock), prevRandaoSnapshot)
     *      drawIndex  = keccak256(revealSeed, playerAddr, gameId) % 52
     *
     *      Note: blockhash() returns 0 for blocks older than 256. Call within ~51 min.
     */
    function finalizeReveal(uint256 gameId) external {
        Game storage game = games[gameId];
        require(game.status == GameStatus.PendingReveal, "Not in pending reveal phase");
        require(block.number > game.revealBlock, "Target block not yet mined");

        bytes32 blockHash = blockhash(game.revealBlock);
        require(blockHash != bytes32(0), "Block hash unavailable (>256 blocks passed)");

        game.revealSeed = uint256(keccak256(abi.encodePacked(blockHash, game.prevRandaoSnapshot)));
        game.revealDeadline = block.timestamp + REVEAL_TIMEOUT;
        game.status = GameStatus.Revealing;

        emit RevealStarted(gameId, game.revealSeed, game.revealDeadline);
    }

    // ─── Phase 2: Reveal ───────────────────────────────────────────────────────

    /**
     * @dev Reveal phase: submit ZK proof.
     *      drawIndex is computed from revealSeed set by finalizeReveal() and cannot be pre-simulated.
     *      The ZK proof proves: deckCards[drawIndex] = drawnCard given deckCommitment.
     */
    function revealCard(
        uint256 gameId,
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c,
        bytes32 drawCommitment,
        uint256 drawnCard
    ) external {
        Game storage game = games[gameId];
        require(game.status == GameStatus.Revealing, "Game is not in reveal phase");
        require(hasJoined[gameId][msg.sender], "Not a player in this game");
        require(block.timestamp <= game.revealDeadline, "Reveal deadline has passed");

        uint256 playerIdx = _playerIndex[gameId][msg.sender];
        Player storage player = _players[gameId][playerIdx];
        require(!player.hasRevealed, "Already revealed");
        require(drawnCard < 52, "Invalid card index");

        // drawIndex is determined by on-chain randomness — player cannot choose it
        uint256 drawIndex = getPlayerDrawIndex(gameId, msg.sender);

        // Verify ZK proof with the externally-determined drawIndex
        uint256[5] memory publicInputs = [
            uint256(player.deckCommitment),
            uint256(drawCommitment),
            drawIndex,
            gameId,
            uint256(player.playerCommitment)
        ];
        require(
            drawVerifier.verifyProof(a, b, c, publicInputs),
            "Invalid card draw proof"
        );

        player.drawnCard = drawnCard;
        player.hasRevealed = true;
        game.revealedCount++;

        emit PlayerRevealed(gameId, msg.sender, drawnCard, drawIndex);
    }

    // ─── Phase 2 → 3: Close ────────────────────────────────────────────────────

    /**
     * @dev Close the game after reveal phase. Winner is highest card among revealed players.
     *      Players who did not reveal forfeit their entry fee (goes to accumulatedFees).
     */
    function closeGame(uint256 gameId) external {
        Game storage game = games[gameId];
        require(game.status == GameStatus.Revealing, "Game is not in reveal phase");
        require(
            game.revealedCount == game.playerCount ||
            block.timestamp > game.revealDeadline,
            "Reveal phase has not ended yet"
        );

        Player[] storage players = _players[gameId];

        // If nobody revealed, cancel and refund all
        if (game.revealedCount == 0) {
            for (uint256 i = 0; i < players.length; i++) {
                paymentToken.transfer(players[i].addr, entryFee);
            }
            game.status = GameStatus.Cancelled;
            emit GameCancelled(gameId);
            return;
        }

        // Find winner among revealed players only
        uint256 highestScore = 0;
        address winner = address(0);
        uint256 highestCard = 0;

        for (uint256 i = 0; i < players.length; i++) {
            if (!players[i].hasRevealed) continue;
            uint256 score = _cardScore(players[i].drawnCard);
            if (score > highestScore) {
                highestScore = score;
                winner = players[i].addr;
                highestCard = players[i].drawnCard;
            }
        }

        // Prize pool = revealed players only; forfeited fees go to contract
        uint256 revealedPool = game.revealedCount * entryFee;
        uint256 forfeitedFees = (game.playerCount - game.revealedCount) * entryFee;
        uint256 fee = revealedPool * FEE_PERCENT / 100;
        uint256 prize = revealedPool - fee;

        accumulatedFees += fee + forfeitedFees;

        require(paymentToken.transfer(winner, prize), "Prize transfer failed");

        game.status = GameStatus.Finished;
        game.winner = winner;
        game.highestCardValue = highestCard;

        emit GameFinished(gameId, winner, prize, highestCard);
    }

    // ─── Utility ───────────────────────────────────────────────────────────────

    /**
     * @dev Cancel the game (creator only, commit phase only). Refunds all committed players.
     */
    function cancelGame(uint256 gameId) external {
        Game storage game = games[gameId];
        require(game.status == GameStatus.Open, "Game is not in commit phase");
        require(msg.sender == game.creator, "Only creator can cancel");

        Player[] storage players = _players[gameId];
        for (uint256 i = 0; i < players.length; i++) {
            paymentToken.transfer(players[i].addr, entryFee);
        }

        game.status = GameStatus.Cancelled;
        emit GameCancelled(gameId);
    }

    /**
     * @dev Get the deterministic drawIndex for a player (only valid after startReveal).
     *      drawIndex = keccak256(revealSeed, playerAddr, gameId) % 52
     */
    function getPlayerDrawIndex(uint256 gameId, address player) public view returns (uint256) {
        Game storage game = games[gameId];
        require(game.revealSeed != 0, "Reveal has not started");
        return uint256(keccak256(abi.encodePacked(game.revealSeed, player, gameId))) % 52;
    }

    function getGame(uint256 gameId) external view returns (Game memory) {
        return games[gameId];
    }

    function getGamePlayers(uint256 gameId) external view returns (Player[] memory) {
        return _players[gameId];
    }

    function withdrawFees(address to) external {
        require(msg.sender == admin, "Only admin can withdraw fees");
        require(accumulatedFees > 0, "No fees to withdraw");
        uint256 amount = accumulatedFees;
        accumulatedFees = 0;
        require(paymentToken.transfer(to, amount), "Fee transfer failed");
    }

    /**
     * @dev Card score: rank = card % 13 (0=A, 1=2, ..., 12=K)
     *      Ace=14, K=13, ..., 2=2. Suit tiebreaker: Spades > Hearts > Diamonds > Clubs.
     *      Score = rankValue * 4 + (3 - suitIndex)
     */
    function _cardScore(uint256 card) internal pure returns (uint256) {
        uint256 rank = card % 13;
        uint256 suitIndex = card / 13;
        uint256 rankValue = rank == 0 ? 14 : rank + 1;
        return rankValue * 4 + (3 - suitIndex);
    }
}

contracts/GamingItemTrade.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./NFTNoteBase.sol";
import "./verifiers/IGroth16Verifier.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title GamingItemTrade
 * @dev F5: Gaming Item Trade - P2P marketplace for privately trading gaming items.
 *
 *      Item Note structure: Poseidon(pkX, pkY, itemId, itemType, itemAttributes, gameId, salt)
 *      Payment Note structure: Poseidon(sellerPkX, sellerPkY, price, paymentToken, paymentSalt)
 *
 *      Flow:
 *        1. Seller registers item (registerItem)
 *        2. Seller lists item for sale (listItem)
 *        3. Buyer pays escrow + submits ZK pubkey (purchaseItem)
 *        4. Seller generates ZK proof using buyer's pubkey, executes trade (executeTradeForBuyer)
 *        5. Payment released to seller; new item note created for buyer
 */
contract GamingItemTrade is NFTNoteBase {
    IGamingItemTradeVerifier public tradeVerifier;
    IERC20 public paymentToken;
    address public admin;
    uint256 public nextListingId = 1;

    struct Listing {
        address seller;
        bytes32 itemNoteHash;
        uint256 gameId;
        uint256 itemId;
        uint256 price;      // token amount (ERC20)
        bool active;
        address buyer;      // set after purchaseItem()
        uint256 buyerPkX;   // buyer ZK pubkey X
        uint256 buyerPkY;   // buyer ZK pubkey Y
    }

    mapping(uint256 => Listing) public listings;

    // gameId => itemId => registered
    mapping(uint256 => mapping(uint256 => bool)) public registeredItems;

    event ItemRegistered(uint256 indexed gameId, uint256 indexed itemId, bytes32 noteHash);
    event ItemListed(address indexed seller, uint256 indexed listingId, uint256 price);
    event ItemPurchased(address indexed buyer, uint256 indexed listingId, uint256 buyerPkX, uint256 buyerPkY);
    event ItemTradeCompleted(uint256 indexed listingId, bytes32 oldNote, bytes32 newNote);
    event ListingCancelled(uint256 indexed listingId);

    constructor(address _tradeVerifier, address _paymentToken) {
        tradeVerifier = IGamingItemTradeVerifier(_tradeVerifier);
        paymentToken = IERC20(_paymentToken);
        admin = msg.sender;
    }

    /**
     * @dev Register a gaming item into the private trading system.
     * @param noteHash The commitment to the item note
     * @param gameId The game ecosystem identifier
     * @param itemId The item token ID
     * @param encryptedNote ECDH-encrypted note data for the owner
     */
    function registerItem(
        bytes32 noteHash,
        uint256 gameId,
        uint256 itemId,
        bytes memory encryptedNote
    ) external {
        require(!registeredItems[gameId][itemId], "Item already registered");
        registeredItems[gameId][itemId] = true;
        _createNote(noteHash, encryptedNote);
        emit ItemRegistered(gameId, itemId, noteHash);
    }

    /**
     * @dev List a registered item for sale.
     * @param itemNoteHash The current valid note hash for the item
     * @param gameId The game ecosystem identifier
     * @param itemId The item token ID
     * @param price Sale price in payment token units
     */
    function listItem(
        bytes32 itemNoteHash,
        uint256 gameId,
        uint256 itemId,
        uint256 price
    ) external noteExists(itemNoteHash) {
        require(price > 0, "Price must be greater than zero");
        uint256 listingId = nextListingId++;
        listings[listingId] = Listing({
            seller: msg.sender,
            itemNoteHash: itemNoteHash,
            gameId: gameId,
            itemId: itemId,
            price: price,
            active: true,
            buyer: address(0),
            buyerPkX: 0,
            buyerPkY: 0
        });
        emit ItemListed(msg.sender, listingId, price);
    }

    /**
     * @dev Buyer pays escrow and submits their ZK public key.
     *      Tokens are held in this contract until the trade completes or is cancelled.
     * @param listingId The listing ID
     * @param buyerPkX Buyer's ZK public key X coordinate
     * @param buyerPkY Buyer's ZK public key Y coordinate
     */
    function purchaseItem(
        uint256 listingId,
        uint256 buyerPkX,
        uint256 buyerPkY
    ) external {
        Listing storage listing = listings[listingId];
        require(listing.active, "Listing not active");
        require(listing.buyer == address(0), "Already purchased");
        require(buyerPkX != 0 || buyerPkY != 0, "Invalid buyer pubkey");

        require(
            paymentToken.transferFrom(msg.sender, address(this), listing.price),
            "Payment transfer failed"
        );

        listing.buyer = msg.sender;
        listing.buyerPkX = buyerPkX;
        listing.buyerPkY = buyerPkY;

        emit ItemPurchased(msg.sender, listingId, buyerPkX, buyerPkY);
    }

    /**
     * @dev Seller submits ZK proof and completes the trade.
     *      Spends the old item note, creates a new one for the buyer, and releases payment.
     * @param listingId The listing ID
     * @param a Groth16 proof point a
     * @param b Groth16 proof point b
     * @param c Groth16 proof point c
     * @param newItemHash New item note hash committed to buyer's pubkey
     * @param paymentNoteHash Payment note hash
     * @param nullifier Nullifier to prevent double-spend
     * @param encryptedNote ECDH-encrypted note data for the buyer
     */
    function executeTradeForBuyer(
        uint256 listingId,
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c,
        bytes32 newItemHash,
        bytes32 paymentNoteHash,
        bytes32 nullifier,
        bytes memory encryptedNote
    ) external nullifierNotUsed(nullifier) {
        Listing storage listing = listings[listingId];
        require(listing.active, "Listing not active");
        require(listing.seller == msg.sender, "Only seller can execute trade");
        require(listing.buyer != address(0), "No buyer yet");

        bytes32 oldItemHash = listing.itemNoteHash;
        require(notes[oldItemHash] == NoteState.Valid, "Note does not exist or already spent");

        uint256[5] memory publicInputs = [
            uint256(oldItemHash),
            uint256(newItemHash),
            uint256(paymentNoteHash),
            listing.gameId,
            uint256(nullifier)
        ];

        require(
            tradeVerifier.verifyProof(a, b, c, publicInputs),
            "Invalid trade proof"
        );

        _spendNote(oldItemHash, nullifier);
        _createNote(newItemHash, encryptedNote);

        listing.active = false;

        require(
            paymentToken.transfer(listing.seller, listing.price),
            "Payment release failed"
        );

        emit ItemTradeCompleted(listingId, oldItemHash, newItemHash);
    }

    /**
     * @dev Cancel an active listing. Refunds buyer if payment was made.
     * @param listingId The listing ID to cancel
     */
    function cancelListing(uint256 listingId) external {
        Listing storage listing = listings[listingId];
        require(listing.seller == msg.sender, "Only seller can cancel");
        require(listing.active, "Listing not active");

        listing.active = false;

        if (listing.buyer != address(0)) {
            require(
                paymentToken.transfer(listing.buyer, listing.price),
                "Refund failed"
            );
        }

        emit ListingCancelled(listingId);
    }

    /**
     * @dev Returns all listings (including inactive ones).
     */
    function getListings() external view returns (Listing[] memory) {
        uint256 total = nextListingId - 1;
        Listing[] memory result = new Listing[](total);
        for (uint256 i = 0; i < total; i++) {
            result[i] = listings[i + 1];
        }
        return result;
    }

    /**
     * @dev Returns a single listing by ID.
     */
    function getListing(uint256 listingId) external view returns (Listing memory) {
        return listings[listingId];
    }
}

contracts/LootBoxOpen.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./NFTNoteBase.sol";
import "./verifiers/IGroth16Verifier.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title LootBoxOpen
 * @dev F4: Loot Box Open - Verifiable random loot box opening with provably
 *      fair outcome generation using Poseidon-based VRF.
 *
 *      Box Note structure: Poseidon(pkX, pkY, boxId, boxType, boxSalt)
 *      Outcome Note structure: Poseidon(pkX, pkY, itemId, itemRarity, itemSalt)
 */
contract LootBoxOpen is NFTNoteBase {
    ILootBoxVerifier public boxVerifier;
    IERC20 public paymentToken;
    address public admin;
    uint256 public boxPrice;
    uint256 public nextBoxId = 1;

    // boxId => registered
    mapping(uint256 => bool) public registeredBoxes;
    mapping(uint256 => address) public boxOwner;
    mapping(uint256 => uint256) public boxTypes;
    mapping(address => uint256[]) private userBoxIds;

    event BoxRegistered(uint256 indexed boxId, bytes32 noteHash);
    event BoxOpened(bytes32 indexed boxCommitment, bytes32 indexed outcomeCommitment, bytes32 nullifier, uint256 vrfOutput);
    event BoxMinted(address indexed buyer, uint256 indexed boxId, uint256 boxType);
    event PriceUpdated(uint256 newPrice);

    constructor(address _boxVerifier, address _paymentToken, uint256 _boxPrice) {
        boxVerifier = ILootBoxVerifier(_boxVerifier);
        paymentToken = IERC20(_paymentToken);
        boxPrice = _boxPrice;
        admin = msg.sender;
    }

    /**
     * @dev Purchase a loot box with ERC20 tokens.
     */
    function mintBox(uint256 boxType) external returns (uint256) {
        require(
            paymentToken.transferFrom(msg.sender, address(this), boxPrice),
            "Payment failed"
        );

        uint256 boxId = nextBoxId++;
        boxOwner[boxId] = msg.sender;
        boxTypes[boxId] = boxType;
        userBoxIds[msg.sender].push(boxId);

        emit BoxMinted(msg.sender, boxId, boxType);
        return boxId;
    }

    /**
     * @dev Register a sealed loot box into the private system.
     *      Only the box owner can register.
     */
    function registerBox(
        bytes32 noteHash,
        uint256 boxId,
        bytes memory encryptedNote
    ) external {
        require(boxOwner[boxId] == msg.sender, "Not box owner");
        require(!registeredBoxes[boxId], "Box already registered");
        registeredBoxes[boxId] = true;
        _createNote(noteHash, encryptedNote);
        emit BoxRegistered(boxId, noteHash);
    }

    /**
     * @dev Open a loot box using a ZK proof with Poseidon VRF randomness.
     *      Spends the box note and creates an outcome note.
     */
    function openBox(
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c,
        bytes32 boxCommitment,
        bytes32 outcomeCommitment,
        uint256 vrfOutput,
        uint256 boxId,
        bytes32 nullifier,
        bytes memory encryptedNote
    ) external noteExists(boxCommitment) nullifierNotUsed(nullifier) {
        // Verify ZK proof
        uint256[5] memory publicInputs = [
            uint256(boxCommitment),
            uint256(outcomeCommitment),
            vrfOutput,
            boxId,
            uint256(nullifier)
        ];

        require(
            boxVerifier.verifyProof(a, b, c, publicInputs),
            "Invalid box opening proof"
        );

        // Spend box note, create outcome note
        _spendNote(boxCommitment, nullifier);
        _createNote(outcomeCommitment, encryptedNote);

        emit BoxOpened(boxCommitment, outcomeCommitment, nullifier, vrfOutput);
    }

    /**
     * @dev Get all box IDs owned by a user.
     */
    function getMyBoxes(address user) external view returns (uint256[] memory) {
        return userBoxIds[user];
    }

    /**
     * @dev Get box info by ID.
     */
    function getBoxInfo(uint256 boxId) external view returns (address owner, uint256 boxType, bool registered) {
        return (boxOwner[boxId], boxTypes[boxId], registeredBoxes[boxId]);
    }

    /**
     * @dev Update box price (admin only).
     */
    function setBoxPrice(uint256 _price) external {
        require(msg.sender == admin, "Only admin");
        boxPrice = _price;
        emit PriceUpdated(_price);
    }

    /**
     * @dev Withdraw accumulated tokens (admin only).
     */
    function withdrawTokens(address to) external {
        require(msg.sender == admin, "Only admin");
        uint256 balance = paymentToken.balanceOf(address(this));
        require(balance > 0, "No tokens to withdraw");
        paymentToken.transfer(to, balance);
    }
}

contracts/NFTNoteBase.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title NFTNoteBase
 * @dev Base contract for ZK NFT note management.
 *      Manages note states and nullifier tracking for private NFT operations.
 */
contract NFTNoteBase {
    enum NoteState { Invalid, Valid, Spent }

    // note hash => state
    mapping(bytes32 => NoteState) public notes;

    // nullifier => used
    mapping(bytes32 => bool) public nullifiers;

    // Encrypted note storage (ECDH encrypted)
    mapping(bytes32 => bytes) public encryptedNotes;

    event NoteCreated(bytes32 indexed noteHash, bytes encryptedNote);
    event NoteSpent(bytes32 indexed noteHash, bytes32 indexed nullifier);

    modifier noteExists(bytes32 noteHash) {
        require(notes[noteHash] == NoteState.Valid, "Note does not exist or already spent");
        _;
    }

    modifier nullifierNotUsed(bytes32 nullifier) {
        require(!nullifiers[nullifier], "Nullifier already used");
        _;
    }

    function _createNote(bytes32 noteHash, bytes memory encryptedNote) internal {
        require(notes[noteHash] == NoteState.Invalid, "Note already exists");
        notes[noteHash] = NoteState.Valid;
        encryptedNotes[noteHash] = encryptedNote;
        emit NoteCreated(noteHash, encryptedNote);
    }

    function _spendNote(bytes32 noteHash, bytes32 nullifier) internal {
        require(notes[noteHash] == NoteState.Valid, "Note not valid");
        require(!nullifiers[nullifier], "Nullifier already used");
        notes[noteHash] = NoteState.Spent;
        nullifiers[nullifier] = true;
        emit NoteSpent(noteHash, nullifier);
    }

    function getNoteState(bytes32 noteHash) external view returns (NoteState) {
        return notes[noteHash];
    }

    function isNullifierUsed(bytes32 nullifier) external view returns (bool) {
        return nullifiers[nullifier];
    }
}

